{
  "packet_hash": "902e865eba0ae061413cf9a539127966fe2073d89e860ae2d99fbaf7d214d025",
  "author": "/root/sketch_trial_a",
  "parent_revision": 0,
  "title": "軽減済みの守り・補充・コピー役を回すスペルウィッチ",
  "hypothesis": "ローテーションのウィッチ。0PPのフィーリン、0PPのサミー＆マリー、スターライトゴッデスを左3枚に残してまとめて複製し、次ターンも同じ3役を使える形を探る。過剰反応は初回の捨て札3枚を用意する役へ読み替える。以後はサミー＆マリーの2枚ドローと通常ドロー1枚を次の捨て札にでき、コピー役を引き直す必要も減る。軽減し直さずに必殺・守護・オーラを置き続けられる点が利益の仮説。初回の部品確保と守りながら軽減する過程、攻めへの接続が未解決のため、強さや推薦を確定しない。",
  "change": "主役指定なしで全212枚の本文・進化・参照効果・注記を走査。軍配を高元コスト札に合わせる案、哲学者でリンクルを大量に引く案は公開された既存用法を確認し選ばなかった。本案では、既知のゴッデスによる単発の魔手札複製から対象を変更し、低コストの守り、毎回の捨て札を賄う補充、コピー役自身という3役の循環を調べる。コピー一般やゴッデス入りスペルウィッチそのものを新発見とはしない。",
  "roles": [
    {
      "card_id": 10502110,
      "access": "deck",
      "role": "核。初回は2枚を手札に必要とし、右側の1枚を使って左側に残す同名もコピーする。コピーで得た同名も次回の起動役にする。"
    },
    {
      "card_id": 10934120,
      "access": "deck",
      "role": "核。早く引いた1枚を10回以上軽減して0PPにし、その状態のコピーを守護・必殺・オーラとして使う。コピーの別個体もこの役割を担う。"
    },
    {
      "card_id": 10832110,
      "access": "deck",
      "role": "核。5回以上軽減して0PPにし、各コピー回の2枚ドローで次回の捨て札を賄う。相手も毎回1枚引く負担を含む。"
    },
    {
      "card_id": 10931310,
      "access": "deck",
      "role": "初回の捨て札を1PPで3枚作る。コピーできない局面では従来通りスペル枚数を供給する。"
    },
    {
      "card_id": 10031320,
      "access": "effect",
      "via": [
        10931310
      ],
      "role": "過剰反応で得る3枚。起動手順ではプレイせず、進化時に全3枚を捨てる。"
    },
    {
      "card_id": 10833310,
      "access": "deck",
      "role": "序盤からの補充と回復。5回以上軽減対象へスペルブーストしながら手札を整える基盤。"
    },
    {
      "card_id": 10834110,
      "access": "deck",
      "role": "コピーを続けない局面の疾走による攻めを担う候補。20回達成や進化権を自動で確保した扱いにはしない。"
    }
  ],
  "steps": [
    {
      "action": "指定状態の計算を開始する。7ターン目の通常ドロー後、場は空、手札は左からF=0PPフィーリン、S=0PPサミー＆マリー、G1=ゴッデス、G2=ゴッデス、過剰反応。FとSは手札でそれぞれ10回以上・5回以上スペルブースト済みとする。この状態までの到達率は未検証。",
      "resources": "7PP、手札5枚、場0/5、EP1、SEP2。手札左3枚はF/S/G1。コピー状態の保持は固定したゴッデスのユーザー注記を根拠にする。",
      "result": "成立させるべき開始条件を固定する。7ターン目にこの手札が普通に揃う、序盤を無傷で過ごす、とは主張しない。",
      "evidence": [
        {
          "card_id": 10934120,
          "field": "skill_text",
          "quote": "【スペルブースト時】これのコストを-1する。\n\n【必殺】\n【守護】\n【オーラ】"
        },
        {
          "card_id": 10832110,
          "field": "skill_text",
          "quote": "【スペルブースト時】これのコストを-1する。\n\n【ファンファーレ】自分のデッキから2枚を引く。相手は自身のデッキから1枚を引く。"
        },
        {
          "card_id": 10502110,
          "field": "note",
          "quote": "状態ごとコピー(スペブ回数・融合カウント・バフ込み)+同名3枚制限の実質突破が本体。"
        }
      ]
    },
    {
      "action": "過剰反応を1PPで使い、次に右側のG2を5PPでプレイする。G2をEPで進化し、得た真理の召喚3枚を捨てる。残した左3枚F/S/G1をコピーする。",
      "resources": "PP7→6→1。手札5→7→6→3→6。場0→1。EP1→0、SEP2のまま。最大手札7枚で上限9を超えない。",
      "result": "手札にF/S/G1と、そのコピーF/S/Gを各1枚持つ。捨て札3枚は生成物であり、山札から引いた重要札の捨てを初回は要求しない。",
      "evidence": [
        {
          "card_id": 10931310,
          "field": "skill_text",
          "quote": "『真理の召喚』3枚を自分の手札に加える。"
        },
        {
          "card_id": 10502110,
          "field": "skill_text",
          "quote": "【進化時】自分の手札3枚を選ぶ。それを捨てる。自分の手札左から3枚のコピー1枚ずつを非公開で自分の手札に加える。"
        }
      ]
    },
    {
      "action": "元のFとSを0PPでプレイする。Sで自分は2枚、相手は1枚引く。元のG1とコピーしたF/S/Gは手札へ残す。",
      "resources": "PP1のまま。手札6→5→4→6。場1→2→3。EP0/SEP2。手札の左端はG1、その後ろにコピーF/S/G、最後に新たな2枚。",
      "result": "必殺・守護・オーラを持つ4/6と1/2の補充役、進化したゴッデスを場に置く。相手への1ドローも発生。次ターンの自分の通常ドローで、コピー3役とは別に新規カード3枚を持てる。",
      "evidence": [
        {
          "card_id": 10934120,
          "field": "skill_text",
          "quote": "【スペルブースト時】これのコストを-1する。\n\n【必殺】\n【守護】\n【オーラ】"
        },
        {
          "card_id": 10832110,
          "field": "skill_text",
          "quote": "【スペルブースト時】これのコストを-1する。\n\n【ファンファーレ】自分のデッキから2枚を引く。相手は自身のデッキから1枚を引く。"
        }
      ]
    },
    {
      "action": "8ターン目、通常ドロー後に左端のG1を5PPでプレイする。SEPで超進化し、前ターンの補充2枚と今ターンの通常ドロー1枚を捨て、左3枚のコピーF/S/Gを再びコピーする。前回のF/Sを0PPでプレイする。",
      "resources": "PP8→3。手札7→6→3→6→5→4→6。EP0/SEP2→1。開始時の既存盤面は2枚以下という分岐で、追加3体を置いて5枚以下に収める。場が埋まる場合や捨てられない重要札を引いた場合はこの反復を選ばない。",
      "result": "5PPとSEP1で、次のコピー役・軽減済み守り・補充を手札に残しつつ、F/Sを各1体追加。毎回ゴッデスを山札から引く必要はなくなる。新規ドローを捨てることは手札の質を上げる補充にはなっていない。",
      "evidence": [
        {
          "card_id": 10502110,
          "field": "skill_text",
          "quote": "【進化時】自分の手札3枚を選ぶ。それを捨てる。自分の手札左から3枚のコピー1枚ずつを非公開で自分の手札に加える。"
        },
        {
          "card_id": 10832110,
          "field": "skill_text",
          "quote": "【スペルブースト時】これのコストを-1する。\n\n【ファンファーレ】自分のデッキから2枚を引く。相手は自身のデッキから1枚を引く。"
        },
        {
          "keyword": "進化時",
          "quote": "EPを使って進化したときやSEPを使って超進化したときに働く能力。"
        }
      ]
    },
    {
      "action": "9ターン目も同じ空き・捨て札条件を満たす場合だけ、残るSEP1で最後のコピーを行う。得たF/Sを1組温存すれば、追加の進化権なしで後から4組目として使える。",
      "resources": "PP9→4。手札は同じ7→6→3→6→5→4→6。EP0/SEP1→0。3回のコピーには合計EP1とSEP2を消費。4組目を実際に出すには、最後のコピー後にさらに場の空き2枚が必要。前の身体の生存を前提にPPや打点を加算しない。",
      "result": "指定分岐では、初めに軽減したF/S各1枚から合計4枚ずつを用意できる。無限反復ではなく、進化権を使い切る有限の計画。4枚目の配置やその後の勝利はこの計算では証明していない。",
      "evidence": [
        {
          "card_id": 10502110,
          "field": "skill_text",
          "quote": "【進化時】自分の手札3枚を選ぶ。それを捨てる。自分の手札左から3枚のコピー1枚ずつを非公開で自分の手札に加える。"
        },
        {
          "card_id": 10934120,
          "field": "skill_text",
          "quote": "【スペルブースト時】これのコストを-1する。\n\n【必殺】\n【守護】\n【オーラ】"
        },
        {
          "card_id": 10832110,
          "field": "skill_text",
          "quote": "【スペルブースト時】これのコストを-1する。\n\n【ファンファーレ】自分のデッキから2枚を引く。相手は自身のデッキから1枚を引く。"
        },
        {
          "source_hash": "204452897e25869634aea4a4bc21cc1837ba16f8cd407d899e698af79802ea4b",
          "quote": "各ターン5PPと進化権1回が必要。"
        }
      ]
    }
  ],
  "plan": {
    "early": "既存スペルウィッチの軽い除去、ティコの生成スペル、鋼鉄の微睡み等を使って手札を整える。フィーリンとサミー＆マリーを早く引いて軽減しつつ、ゴッデス2枚を抱える負担を検証する。過剰反応は初回の捨て札用を1枚残す案だが、早いスペル使用と競合する。実際の序盤手順・到達頻度は未完成。",
    "transition": "0PPのF/Sとゴッデス2枚、捨て札3枚、進化権が揃うときに限りコピーへ切り替える。コピーで増えるFは直接採用から新しく引くFと違って再度10回軽減しなくてよい。相手の横展開に5PPと進化攻撃だけでは対処できない場合は、コピーを延期して除去へPPを使う。",
    "finish": "主な攻めは、守護・オーラのFを含む場を繰り返し作って残った身体で攻撃する可能性を試す。場に残ることを確定打点にはしない。通常のテトラ＆ラティカの疾走は代替の攻めとして残すが、コピー中に新しいドローを捨て続けると決着札を保持しづらく、3回のコピー後は進化権もない。良い決着札を引いたら反復を打ち切る必要がある。この接続が弱ければ本案は見送る。20回スペルブーストの16点等をこのコピー計算へ足していない。",
    "without_core": "ゴッデスが2枚揃わない場合、0PPのF/Sは普通に使い、軽減済みのアラ・テトラ＆ラティカ等へ進む。コピー対象が3種類そろわないゴッデスは5PPの重い札になりうる。単発での有用なコピーに留める場合も、循環が成立した実績に数えない。",
    "allocation": "比較材料は初期packetのGame8スペルウィッチ40枚からジンジャー3枚をゴッデス3枚へ交換したもの。公開compareで交換総数3枚、フォロワー24/スペル16は両方同じ、採用上の問題なしを確認。過剰反応・F・Sはもともと各3枚で、初回比較では増やさない。これにより7PPの守護展開と複数回スペルブーストを失い、5PPの状態保持コピーとその反復へ3枠を使う。40枚は差分確認用の仮説で、完成デッキとして推薦しない。",
    "comparison": "利益仮説は、0PPの必殺・守護・オーラという少ない代役の役割を4枚目まで用意し、通常ドローを再び軽減する待ち時間とコピー役の引き直しを減らすこと。単なる2枚目の複製より、補充役とコピー役も増やして3回の捨て札費用を賄う点を試す。負担は初回の5種類相当の手札条件（ゴッデス2枚）、場の3枠、5PPを使うターンの防御、進化権3回、相手への毎回1ドロー、捨てた札から攻めへ転じにくいこと。既存のジンジャーを3枚普通に使う案より良いかは未確認。既存Webには魔手札をゴッデスで増やす用法とゴッデス入りスペルの一般言及があり、本3役循環の既出は検索範囲で見つけていないだけで新規性は未確定。"
  },
  "questions": [
    {
      "question": "序盤の必要な除去と補充を行いながら、7ターン目までにF/Sの軽減、ゴッデス2枚、適切な左3枚をどの程度揃えられるか。",
      "tag": null,
      "why": "指定状態だけ成立しても、普段揃わないなら3枠の交換利益がない。"
    },
    {
      "question": "同じ初手・同じ相手盤面を使う比較で、ジンジャーを残す案よりコピーへの移行が防御と攻めの両方を改善する局面があるか。",
      "tag": null,
      "why": "0PPの守護を増やすだけで、序盤の負担・失ったスペルブースト・進化権を上回ったと判定しないため。"
    },
    {
      "question": "捨て札にする通常ドローが決着札だった場合、どの時点で反復を打ち切り、何枚の進化権を攻めに残すべきか。",
      "tag": null,
      "why": "補充を次の捨て札だけへ使う循環は、勝ち筋を増やさず延命だけになるおそれがある。"
    },
    {
      "question": "動画本編や画像構築を含め、このF/S/ゴッデスの3役反復が既に共有されているか。",
      "tag": null,
      "why": "Webの未ヒットを独自性の証明にせず、既存のゴッデス入りスペルとの実質差を確認するため。"
    }
  ],
  "uncertainties": [
    "この提出は未検証の種。ゲーム内対戦、勝率推計、Tier認定を行っていない。",
    "開始状態の到達率と具体的な序盤の資源配分は未検証。F/Sを使わず手札に抱える間の防御損失が大きい可能性がある。",
    "新規ドローを3枚捨ててよいという判断と毎ターンの場の空きは相手・引きに依存。全分岐で反復できるとは主張しない。",
    "初回後に大事な札を残すと左3枚へ混ざってコピー対象を変える場合があり、手札の順序を保ったまま決着札を温存できるとは限らない。",
    "3回の進化コピーでEP1/SEP2を使い切る指定計算。追加の進化権や別カードの超進化と二重計上していない。",
    "フィーリンのオーラは選択されないだけで、全体破壊・ランダム除去・戦闘への耐性保証ではない。",
    "公式ページとデータURLの最新再確認は失敗し、能力・合法性・コピー状態保持は固定packetの本文と注記に依拠する。",
    "検索は公開Webの返答本文・抜粋まで。SNS・動画・画像・大会の網羅ではなく、既出でないと断定しない。"
  ],
  "revision": 1,
